/**
 * Post-tsc step: scans dist/**\/*.d.ts for `import type ... from "@ui5/openui5-types/sap/..."`,
 * collects all needed `declare module` blocks (transitively) from @types/openui5,
 * and writes dist/openui5-types.d.ts with only those modules (prefixed).
 *
 * This replaces the full dist/openui5-types.d.ts written by the extract step,
 * trimming it from all 356 @types/openui5 modules down to only the ones actually used.
 */

import ts from "typescript";
import fs from "fs/promises";
import path from "path";
import { createRequire } from "module";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);

const DIST_DIR = path.resolve(__dirname, "../../dist");
const OUT_FILE = path.join(DIST_DIR, "openui5-types.d.ts");
const OPENUI5_TYPES = require.resolve("@types/openui5/sap.ui.core.d.ts");
const MODULE_PREFIX = "@ui5/openui5-types/";

const collectSapImportsFromDts = async () => {
	const entries = await fs.readdir(DIST_DIR, { recursive: true });
	const dtsFiles = entries
		.filter(f => f.endsWith(".d.ts") && f !== "openui5-types.d.ts")
		.map(f => path.join(DIST_DIR, f));

	const sapModules = new Set();
	const filesWithSapImports = new Set();
	for (const file of dtsFiles) {
		const content = await fs.readFile(file, "utf-8");
		const sourceFile = ts.createSourceFile(file, content, ts.ScriptTarget.Latest, true);
		let hasSap = false;
		ts.forEachChild(sourceFile, node => {
			if (
				ts.isImportDeclaration(node) &&
				ts.isStringLiteral(node.moduleSpecifier)
			) {
				const spec = node.moduleSpecifier.text;
				if (spec.startsWith(MODULE_PREFIX + "sap/")) {
					sapModules.add(spec.slice(MODULE_PREFIX.length).replace(/\.js$/, ""));
					hasSap = true;
				}
			}
		});
		if (hasSap) filesWithSapImports.add(file);
	}
	return { sapModules, filesWithSapImports };
};

const findModuleNode = (sourceFile, moduleName) => {
	let found = null;
	ts.forEachChild(sourceFile, node => {
		if (
			ts.isModuleDeclaration(node) &&
			ts.isStringLiteral(node.name) &&
			node.name.text === moduleName
		) {
			found = node;
		}
	});
	return found;
};

const collectTransitiveModules = (sourceFile, entryModules) => {
	const visited = new Set(entryModules);
	const queue = [...entryModules];

	while (queue.length > 0) {
		const moduleName = queue.shift();
		const moduleNode = findModuleNode(sourceFile, moduleName);
		if (!moduleNode || !moduleNode.body) continue;

		const body = moduleNode.body;
		if (!ts.isModuleBlock(body)) continue;

		for (const stmt of body.statements) {
			if (
				ts.isImportDeclaration(stmt) &&
				ts.isStringLiteral(stmt.moduleSpecifier)
			) {
				const dep = stmt.moduleSpecifier.text.replace(/\.js$/, "");
				if (dep.startsWith("sap/") && !visited.has(dep)) {
					visited.add(dep);
					queue.push(dep);
				}
			}
		}
	}

	return visited;
};

const REFERENCE_DIRECTIVE = `/// <reference path="./openui5-types.d.ts" />`;
const REFERENCE_DIRECTIVE_SUBDIRS = `/// <reference path="../openui5-types.d.ts" />`;

const injectReferenceDirective = async (filesWithSapImports) => {
	for (const file of filesWithSapImports) {
		const content = await fs.readFile(file, "utf-8");
		const relPath = path.relative(DIST_DIR, file);
		const isSubdir = relPath.includes(path.sep);
		const directive = isSubdir ? REFERENCE_DIRECTIVE_SUBDIRS : REFERENCE_DIRECTIVE;
		if (content.includes(directive)) continue;
		await fs.writeFile(file, `${directive}\n${content}`, "utf-8");
	}
};

const generate = async () => {
	const { sapModules: entryModules, filesWithSapImports } = await collectSapImportsFromDts();
	if (entryModules.size === 0) {
		console.log("bundle-openui5-types: no @ui5/openui5-types/ imports found, skipping.");
		return;
	}

	const source = await fs.readFile(OPENUI5_TYPES, "utf-8");
	const sourceFile = ts.createSourceFile(OPENUI5_TYPES, source, ts.ScriptTarget.Latest, true);
	const printer = ts.createPrinter({ newLine: ts.NewLineKind.LineFeed });

	const allModules = collectTransitiveModules(sourceFile, entryModules);

	const blocks = [...allModules].sort().map(name => {
		const node = findModuleNode(sourceFile, name);
		if (!node) {
			console.warn(`Warning: could not find declare module "${name}" in @types/openui5`);
			return null;
		}
		let text = printer.printNode(ts.EmitHint.Unspecified, node, sourceFile);
		// Rename the module declaration itself
		text = text.replace(`declare module "${name}"`, `declare module "${MODULE_PREFIX}${name}"`);
		// Rename all internal sap/ references in import/export statements
		text = text.replace(/from "sap\//g, `from "${MODULE_PREFIX}sap/`);
		text = text.replace(/from 'sap\//g, `from '${MODULE_PREFIX}sap/`);
		return text;
	}).filter(Boolean);

	const content = [
		"// Auto-generated by bundle-openui5-types. Do not edit.",
		"// Contains sap/ ambient module declarations needed by @ui5/webcomponents-localization.",
		"// Prefixed with @ui5/openui5-types/ to avoid conflicts with @types/openui5.",
		"",
		...blocks,
		"",
	].join("\n");

	await fs.writeFile(OUT_FILE, content, "utf-8");
	console.log(`bundle-openui5-types: trimmed dist/openui5-types.d.ts to ${allModules.size} module declarations`);

	await injectReferenceDirective(filesWithSapImports);
	console.log(`bundle-openui5-types: injected /// <reference> into ${filesWithSapImports.size} .d.ts files`);
};

generate().catch(err => { console.error(err); process.exit(1); });
